<template><el-card><h1>拍照默写批改</h1><el-input-number v-model="documentId" :min="1"/><span style="margin-left:8px">文档 ID</span><el-upload drag :http-request="upload" :show-file-list="false"><p>上传手写默写照片并识别</p><small>当前后端优先读取同名 .txt sidecar 作为 OCR 占位结果，后续可替换 PaddleOCR。</small></el-upload><el-table v-if="items.length" :data="items"><el-table-column prop="answer" label="标准答案"/><el-table-column prop="user_answer" label="识别结果"/><el-table-column prop="status" label="批改"/></el-table></el-card></template>
<script setup>import{ref}from'vue';import{uploadOcrImage}from'@/api/client';const documentId=ref(1);const items=ref([]);async function upload({file}){const form=new FormData();form.append('document_id',documentId.value);form.append('file',file);const{data}=await uploadOcrImage(form);items.value=data.data.result.items}</script>
